class Solution:
    def minInsertions(self, s: str) -> int:
        stack = []
        res = 0
        i = 0
        while i < len(s):
            if s[i] == '(':
                stack.append('(')
                i += 1
            else:
                if i + 1 < len(s) and s[i + 1] == ')':
                    i += 2
                else:
                    res += 1
                    i += 1
                if stack:
                    stack.pop()
                else:
                    res += 1
        return res + 2 * len(stack)

