class Solution {
public:
    int minInsertions(string s) {
        vector<char> st;
        int res = 0, i = 0, n = s.size();
        while (i < n) {
            if (s[i] == '(') {
                st.push_back('(');
                i++;
            } else {
                if (i + 1 < n && s[i + 1] == ')') i += 2;
                else { res++; i++; }
                if (!st.empty()) st.pop_back();
                else res++;
            }
        }
        return res + 2 * (int)st.size();
    }
};

