class Solution {
    public int minInsertions(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        int res = 0, i = 0, n = s.length();
        while (i < n) {
            if (s.charAt(i) == '(') {
                stack.push('(');
                i++;
            } else {
                if (i + 1 < n && s.charAt(i + 1) == ')') i += 2;
                else { res++; i++; }
                if (!stack.isEmpty()) stack.pop();
                else res++;
            }
        }
        return res + 2 * stack.size();
    }
}

